package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

public class JsonParserSequence_nextToken_TriageGen0Test {

    /**
     * Since the constructor is protected and switchToNext is protected, 
     * we use a Testable subclass to access/control the protected state.
     */
    private static class TestableJsonParserSequence extends JsonParserSequence {
        private boolean switchToNextResult = false;
        private boolean suppressNextTokenState = false;

        protected TestableJsonParserSequence(JsonParser[] parsers) {
            super(parsers);
        }

        // Expose protected method for testing
        @Override
        protected boolean switchToNext() {
            return switchToNextResult;
        }

        // Use reflection or a setter to manipulate the private _suppressNextToken field
        // For the sake of this test, we assume we can set it via a helper if needed, 
        // but since I cannot modify the source, I will use a subclass trick if possible.
        // However, the logic is in the parent. We'll use reflection to set the private field.
        public void setSuppressNextToken(boolean value) throws Exception {
            java.lang.reflect.Field field = JsonParserSequence.class.getDeclaredField("_suppressNextToken");
            field.setAccessible(true);
            field.set(this, value);
        }

        public void setSwitchToNextResult(boolean result) {
            this.switchToNextResult = result;
        }
    }

    @Test
    public void testNextToken_DelegateIsNull() throws IOException {
        // To test delegate == null, we need to bypass the factory or use reflection
        // because the constructor takes parsers. If parsers is null or empty, 
        // the internal delegate might be null depending on implementation.
        // Since we can't easily force delegate to null via constructor without knowing implementation details,
        // we mock the sequence behavior if possible, but here we'll rely on the provided logic.

        // In Jackson, if parsers is empty, delegate is null.
        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[0]);

        assertNull(sequence.nextToken());
    }

    @Test
    public void testNextToken_SuppressNextTokenIsTrue() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setSuppressNextToken(true);

        when(mockParser.currentToken()).thenReturn(JsonToken.START_OBJECT);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        // Verify _suppressNextToken was reset to false
        // We verify it by calling nextToken again and seeing if it calls nextToken() instead of currentToken()
        sequence.nextToken();
        verify(mockParser).nextToken();
    }

    @Test
    public void testNextToken_StandardPath_NoSwitch() throws IOException {
        JsonParser mockParser = mock(JsonParser.class);
        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setSwitchToNextResult(false);

        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(mockParser).nextToken();
    }

    @Test
    public void testNextToken_SwitchToNext_HasCurrentToken() throws IOException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);
        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});

        // First call to nextToken() on sequence calls parser1.nextToken()
        // Then switchToNext() returns true (moving to parser2)
        // Then it checks parser2.hasCurrentToken() -> true
        // Then it returns parser2.currentToken()

        sequence.setSwitchToNextResult(true);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.hasCurrentToken()).thenReturn(true);
        when(parser2.currentToken()).thenReturn(JsonToken.FIELD_NAME);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(parser1).nextToken();
        verify(parser2).hasCurrentToken();
        verify(parser2).currentToken();
    }

    @Test
    public void testNextToken_SwitchToNext_NoHasCurrentToken_CallsNextToken() throws IOException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);
        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2});

        sequence.setSwitchToNextResult(true);

        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.hasCurrentToken()).thenReturn(false);
        when(parser2.nextToken()).thenReturn(JsonToken.VALUE_STRING);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.VALUE_STRING, result);
        verify(parser1).nextToken();
        verify(parser2).hasCurrentToken();
        verify(parser2).nextToken();
    }

    @Test
    public void testNextToken_MultipleSwitches() throws IOException {
        JsonParser parser1 = mock(JsonParser.class);
        JsonParser parser2 = mock(JsonParser.class);
        JsonParser parser3 = mock(JsonParser.class);
        TestableJsonParserSequence sequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2, parser3});

        // This is tricky because switchToNext is a single boolean in our test helper.
        // We can simulate a sequence of switches by using a spy or a custom implementation.
        // Let's use a custom subclass to return true twice then false.

        TestableJsonParserSequence multiSwitchSequence = new TestableJsonParserSequence(new JsonParser[]{parser1, parser2, parser3}) {
            private int count = 0;
            @Override
            protected boolean switchToNext() {
                count++;
                if (count == 1) return true;
                if (count == 2) return true;
                return false;
            }
        };

        when(parser1.nextToken()).thenReturn(JsonToken.START_ARRAY);
        when(parser2.hasCurrentToken()).thenReturn(true);
        when(parser2.currentToken()).thenReturn(JsonToken.FIELD_NAME);
        // For the second switch (to parser3)
        // The while loop condition: switchToNext() is called again.
        // The code: t = delegate.hasCurrentToken() ? delegate.currentToken() : delegate.nextToken();
        // Note: The 'delegate' in the real class is actually the parser currently active in the sequence.
        // This implementation detail is complex. Let's assume the 'delegate' updates inside switchToNext.

        // Given the structure, we'll just cover the branch logic.
        multiSwitchSequence.setSwitchToNextResult(true); 
        when(parser1.nextToken()).thenReturn(JsonToken.START_OBJECT);
        when(parser2.hasCurrentToken()).thenReturn(true);
        when(parser2.currentToken()).thenReturn(JsonToken.FIELD_NAME);

        JsonToken result = multiSwitchSequence.nextToken();
        assertEquals(JsonToken.FIELD_NAME, result);
    }
}
